async function downloadFromSharePoint(): Promise<Buffer | null> {
  // No token -> return null (not throw); the caller reads that as 'fall back to a local copy'.
  if (!GRAPH_TOKEN) {
    console.log('  No access token set — skipping download');
    return null;
  }
  // Encode the path to escape spaces/specials, then restore %2F -> / because the Graph drive syntax
  // root:/path:/content needs REAL slashes as separators while the rest stays encoded.
  const encodedPath = encodeURIComponent(SP_FILE_PATH).replace(/%2F/g, '/');
  const result = await graphRequest('GET', `/sites/${SHAREPOINT_SITE}/drive/root:${encodedPath}:/content`);

  // Require 200 AND a body - a 200 with no buffer must not pass as a valid (empty) download.
  if (result.status === 200 && result.buffer) {
    return result.buffer;
  }
  console.log(`  Download failed: HTTP ${result.status}`);
  return null;
}

async function getQATasksHours(storyId: number): Promise<number> {
  const wi = await getWorkItemWithRelations(storyId);
  // Hierarchy-Forward = parent -> child; the target id lives only inside r.url, so regex it out.
  const childIds = (wi.relations || [])
    .filter((r: any) => r.rel === 'System.LinkTypes.Hierarchy-Forward')
    .map((r: any) => parseInt(r.url.match(/workItems\/(\d+)/)[1]));

  if (childIds.length === 0) return 0; // no children -> no hours
  const batch = await adoBatchRequest(childIds, [
    'System.WorkItemType', 'System.Title', 'Microsoft.VSTS.Scheduling.CompletedWork',
  ]);

  let totalHrs = 0;
  for (const child of batch.value) {
    const title = (child.fields?.['System.Title'] || '').toLowerCase();
    // Only QA Tasks count, so non-QA child tasks under the same story don't inflate the total.
    if (child.fields?.['System.WorkItemType'] === 'Task' && title.includes('qa_test')) {
      // CompletedWork = hours actually logged (not RemainingWork); || 0 for a Task with no hours yet, avoids NaN.
      totalHrs += child.fields?.['Microsoft.VSTS.Scheduling.CompletedWork'] || 0;
    }
  }
  return totalHrs;
}

async function getChildBugCount(storyId: number): Promise<number> {
  const wi = await getWorkItemWithRelations(storyId);
  // Same parent->child walk as the hours query; ids are inside r.url.
  const childIds = (wi.relations || [])
    .filter((r: any) => r.rel === 'System.LinkTypes.Hierarchy-Forward')
    .map((r: any) => parseInt(r.url.match(/workItems\/(\d+)/)[1]));

  if (childIds.length === 0) return 0;
  // State is fetched but unused here - keeps the batch shape shared with the bug-sheet rebuild, saving a round-trip.
  const batch = await adoBatchRequest(childIds, ['System.WorkItemType', 'System.State']);
  // Counts EVERY child bug regardless of state -> reflects bugs found, not just bugs still open.
  return batch.value.filter((wi: any) => wi.fields?.['System.WorkItemType'] === 'Bug').length;
}

