async function uploadToSharePoint(fileBuf: Buffer): Promise<boolean> {
  if (!GRAPH_TOKEN) return false; // no token -> report failure rather than attempt an unauthenticated write
  // Same encode-then-restore-/ path dance as the download, so both address the identical file.
  const encodedPath = encodeURIComponent(SP_FILE_PATH).replace(/%2F/g, '/');
  const result = await graphRequest(
    'PUT', // PUT to :/content overwrites the file in place (Graph simple upload; >~4MB would need a chunked session)
    `/sites/${SHAREPOINT_SITE}/drive/root:${encodedPath}:/content`,
    fileBuf,
  );
  // Accept any 2xx, not just 200: Graph create-or-replace returns 201 the first time, 200 after.
  return result.status >= 200 && result.status < 300;
}
